def test_include_router_into_itself():
    router = APIRouter()
    try:
        router.include_router(router)
        print("Failed: Router was included into itself without error")
    except FastAPIError as e:
        print(f"Passed: Caught expected error: {e}")
    except Exception as e:
        print(f"Failed: Caught unexpected exception: {type(e).__name__}: {e}")

if __name__ == "__main__":
    test_include_router_into_itself()

